from ute_ue.utils.param_checker import convert_timestring
import re


class RtgMeasurements(object):
    """Measurements object"""
    def __init__(self, params):
        """Measurements used to parse and validate measurments parameters"""
        try:
            event = params['event']
            del params['event']
        except KeyError:
            raise ValueError('Measurement parameter "event" is mandatory')
        avalible_eutra = ['A1', 'A2', 'A3', 'A4', 'A5', 'A6']
        avalible_nr5g = ['B1-NR', 'B2-NR']

        self.meas = {}
        if event in avalible_eutra:
            self._check_for_unknown_params(params, ['neighbors', 'serv_rsrp', 'serv_rsrq', 'trig', 'amount', 'interval', 'measId_blacklist'])
            eutra_meas = self._validate_and_return_eutra(params)
            eutra_meas.update(self._validate_and_return_common(params))
            eutra_meas.update({'ev': [int(event[1])]})
            self.meas.update({'eutra': eutra_meas})
        elif event in avalible_nr5g:
            self._check_for_unknown_params(params, ['neighbors', 'serv_rsrp', 'serv_rsrq', 'serv_sinr', 'amount', 'interval', 'measId_blacklist'])
            nr5g_meas = self._validate_and_return_nr5g(params)
            nr5g_meas.update(self._validate_and_return_common(params))
            nr5g_meas.update({'ev': [int(event[1])]})
            self.meas.update({'nr5g': nr5g_meas})
        else:
            raise ValueError('Measurement event type {} is incorrect or not supported. Avalible ones are: {}'.
                             format(event, avalible_eutra + avalible_nr5g))

    def get_measurements(self):
        """Return measurements structure that matches UEx's UE.o_meas/2 function"""
        return self.meas

    def _validate_and_return_eutra(self, params):
        eutra = {}
        if 'neighbors' in params:
            eutra.update({'neig': self._get_neigh_list('eutra', params['neighbors'])})
        if 'serv_rsrp' in params and 'serv_rsrq' in params:
            serv_rsrp = self._get_rsrp_rsrq_sinr('serv_rsrp', params['serv_rsrp'])
            serv_rsrq = self._get_rsrp_rsrq_sinr('serv_rsrq', params['serv_rsrq'])
            eutra.update({"serv": {'rsrp': serv_rsrp, 'rsrq': serv_rsrq}})
        if 'trig' in params:
            if params['trig'] in ['any', 'rsrp', 'rsrq']:
                eutra.update({'trig': params['trig']})
            else:
                raise ValueError('trig prarameter should be: rsrp, rsrq or any')

        return eutra

    def _validate_and_return_nr5g(self, params):
        nr5g = {}
        if 'neighbors' in params:
            nr5g.update({'neig': self._get_neigh_list('nr5g', params['neighbors'])})
        if 'serv_rsrp' in params and 'serv_rsrq' in params:
            serv_rsrp = self._get_rsrp_rsrq_sinr('serv_rsrp', params['serv_rsrp'])
            serv_rsrq = self._get_rsrp_rsrq_sinr('serv_rsrq', params['serv_rsrq'])
            nr5g.update({"serv": {'rsrp': serv_rsrp, 'rsrq': serv_rsrq}})

        return nr5g

    def _validate_and_return_common(self, params):
        common_params = {}
        if 'amount' in params:
            if params['amount'] == 'rrc':
                common_params.update({'amount': 'rrc'})
            else:
                common_params.update({'amount': int(params['amount'])})
        if 'interval' in params:
            if params['interval'] == 'rrc':
                common_params.update({'interval': 'rrc'})
            else:
                common_params.update({'interval': int(convert_timestring(params['interval']) * 1000)})
        if 'measId_blacklist' in params:
            meas_id_black_list = self._validate_and_return_meas_id_blacklist(params['measId_blacklist'])
            common_params.update({'meas_id_black_list': meas_id_black_list})

        return common_params

    def _validate_and_return_eutra_neigh_params(self, params):
        neigh_params = {'meas': {}}

        param_to_func_map = {'pci': lambda value: neigh_params.update({'pci': int(value)}),
                             'rsrp': lambda value: neigh_params['meas'].update({'rsrp': self._get_rsrp_rsrq_sinr('rsrp', value)}),
                             'rsrq': lambda value: neigh_params['meas'].update({'rsrq': self._get_rsrp_rsrq_sinr('rsrq', value)}),
                             'earfcn': lambda value: neigh_params.update({'earfcn': int(value)}),
                             'ecgi': lambda value: neigh_params.update({'ecgi': self._validate_and_return_ecgi(value)})}

        for param, value in params.items():
            try:
                param_to_func_map[param](value)
            except KeyError:
                raise ValueError('Unknown parameter {}'.format(param))
        return neigh_params

    def _validate_and_return_nr5g_neigh_params(self, params):
        neigh_params = {'meas': {}}

        param_to_func_map = {'pci': lambda value: neigh_params.update({'pci': int(value)}),
                             'rsrp': lambda value: neigh_params['meas'].update({'rsrp': self._get_rsrp_rsrq_sinr('rsrp', value)}),
                             'rsrq': lambda value: neigh_params['meas'].update({'rsrq': self._get_rsrp_rsrq_sinr('rsrq', value)}),
                             'sinr': lambda value: neigh_params['meas'].update({'sinr': self._get_rsrp_rsrq_sinr('sinr', value)}),
                             'narfcn': lambda value: neigh_params.update({'narfcn': int(value)})
                             }

        for param, value in params.items():
            try:
                param_to_func_map[param](value)
            except KeyError:
                raise ValueError('Unknown parameter {}'.format(param))
        return neigh_params

    def _check_for_unknown_params(self, recived_params, allowed_params):
        for param, _ in recived_params.items():
            if param not in allowed_params:
                raise ValueError('Unknown parameter {}. Supported parameters are: {}'.format(param, allowed_params))

    def _get_neigh_list(self, meas_type, neighbors):
        neighbor_list = []
        for params in self._parse_neigh_params(neighbors):
            if meas_type == 'eutra':
                neighbor_list.append(self._validate_and_return_eutra_neigh_params(params))
            elif meas_type == 'nr5g':
                neighbor_list.append(self._validate_and_return_nr5g_neigh_params(params))

        return neighbor_list

    def _parse_neigh_params(self, params_str):
        parsed_neigh_list = []
        if not params_str.startswith('(') or not params_str.endswith(')'):
            raise ValueError('Invalid neighbor parameter syntax')
        for param_str in params_str[1:-1].split(';'):
            param_str = param_str.strip().replace('(', '{').replace(')', '}').replace(' ', ', ')
            param_str = re.sub(r'mcc:(\d+)', r'mcc:"\1"', param_str)
            param_str = re.sub(r'mnc:(\d+)', r'mnc:"\1"', param_str)  # needed when e.g mnc:08 was provided
            param_str = re.sub(r'(\w+):', r'"\1":', param_str)
            param_str = re.sub(r':(\d+)-(\d+)?', r':(\1,\2)', param_str)

            try:
                param_dict = eval('{{{}}}'.format(param_str))
            except Exception:
                raise ValueError('Invalid neighbor parameter syntax')
            if not isinstance(param_dict, dict):
                raise ValueError('Invalid neighbor parameter syntax')

            parsed_neigh_list.append(param_dict)

        return parsed_neigh_list

    def _get_rsrp_rsrq_sinr(self, name, param):
        if isinstance(param, (int, tuple)):
            return param
        else:
            try:
                return int(param)
            except Exception:
                status = re.search(r'(\d+)-(\d+)', param)
                try:
                    min_value = int(status.group(1))
                    max_value = int(status.group(2))
                    return (min_value, max_value)
                except AttributeError:
                    raise ValueError('Invalid {0} parameter, it should be a single value e.g. {0}=97 or a value in range e.g. {0}=5-92'.format(name))

    def _validate_and_return_ecgi(self, ecgi_dict):
        for param in ['ci', 'tac']:
            if param not in ecgi_dict:
                raise ValueError('neighbor parameter "ecgi" must contain "{}" parameter'.format(param))
        if 'plmn' in ecgi_dict:
            if 'mcc' not in ecgi_dict['plmn'] or 'mnc' not in ecgi_dict['plmn']:
                raise ValueError('neighbor parameter "plmn" must contain both "mnc" and "mcc" parameters')
            else:
                mcc = int(ecgi_dict['plmn']['mcc'])
                mnc = int(ecgi_dict['plmn']['mnc'])
                ecgi_dict.update({'plmn': [(mcc, mnc)]})
        return ecgi_dict

    def _validate_and_return_meas_id_blacklist(self, meas_id_blacklist):
        meas_id_blacklist = self._get_evaled_meas_id_blacklist(meas_id_blacklist)
        if isinstance(meas_id_blacklist, tuple):
            for meas_id in meas_id_blacklist:
                if isinstance(meas_id, int):
                    self._check_if_meas_id_belongs_to_range_from_1_to_32(meas_id)
                else:
                    raise ValueError('Invalid meas_id_blacklist parameter, it should be a list of integers')
        elif isinstance(meas_id_blacklist, int):
            self._check_if_meas_id_belongs_to_range_from_1_to_32(meas_id_blacklist)
            meas_id_blacklist = (meas_id_blacklist)

        return meas_id_blacklist

    def _get_evaled_meas_id_blacklist(self, meas_id_blacklist):
        try:
            return eval(meas_id_blacklist)
        except Exception:
            raise ValueError('Invalid meas_id_blacklist parameter, it should be either a number'
                             ' or a list of numbers separated by commas in round brackets e.g. meas_id_blacklist=(2, 4, 7)')

    def _check_if_meas_id_belongs_to_range_from_1_to_32(self, meas_id):
        if meas_id < 1 or meas_id > 32:
            raise ValueError('Invalid meas_id_blacklist parameter, measId should be a number between 1 and 32')
